# self-verify
import glob
ok = 0
for fn in sorted(glob.glob(os.path.join(outdir, "*.json"))):
    d = json.load(open(fn, encoding="utf-8"))
    assert all(k in d for k in ("case_id","prediction_text","basis","confidence","trigger")), fn
    assert 0 <= d["confidence"] <= 1, fn
    t = d["trigger"]
    assert all(k in t for k in ("changed_main","reserve_used","disputed","reason")), fn
    ok += 1
print("verified", ok)
cm = sum(1 for r in P.values() if r["trigger"]["changed_main"])
ru = sum(1 for r in P.values() if r["trigger"]["reserve_used"])
di = sum(1 for r in P.values() if r["trigger"]["disputed"])
print("trigger counts changed_main/reserve_used/disputed =", cm, ru, di)
